result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/formgen/src/form.js", "content": "/**
 * Schema-driven form HTML generator with accessibility baked in.
 *
 * Schema fields:
 *   { name, label, type, required?, help?, options? }
 *   type: text | email | number | select | checkbox | textarea
 *   options: [{ value, label }] (select only)
 */

/** Escape text for use in element content. */
function escapeText(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

/** Escape text for use inside a double-quoted attribute value. */
function escapeAttr(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

const CONTROL_TYPES = new Set(['text', 'email', 'number']);

function renderField(field) {
  if (!field || typeof field.name !== 'string' || field.name === '') {
    throw new TypeError('Schema field requires a non-empty "name"');
  }
  const id = `field-${field.name}`;
  const describedby = field.help ? ` aria-describedby="${escapeAttr(`${id}-help`)}"` : '';
  const requiredAttr = field.required ? ' required' : '';

  let control;
  switch (field.type) {
    case 'text':
    case 'email':
    case 'number':
      control =
        `<input type="${field.type}" id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${requiredAttr}${describedby}>`;
      break;
    case 'textarea':
      control =
        `<textarea id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${requiredAttr}${describedby}></textarea>`;
      break;
    case 'select': {
      const options = (field.options ?? [])
        .map(
          (opt) =>
            `<option value="${escapeAttr(opt.value)}">${escapeText(opt.label)}</option>`
        )
        .join('');
      control =
        `<select id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${requiredAttr}${describedby}>${options}</select>`;
      break;
    }
    case 'checkbox':
      control =
        `<input type="checkbox" id="${escapeAttr(id)}" name="${escapeAttr(field.name)}" value="on"${describedby}>`;
      break;
    default:
      throw new TypeError(`Unsupported field type: ${field.type}`);
  }

  // Checkbox: input first, then label text (screen readers announce the
  // control before its description when traversing the label).
  const labelText = escapeText(field.label);
  const inner = field.required
    ? `${control}<label for="${escapeAttr(id)}">${labelText} <span aria-hidden="true">*</span></label>`
    : field.type === 'checkbox'
      ? `${control}<label for="${escapeAttr(id)}">${labelText}</label>`
      : `<label for="${escapeAttr(id)}">${labelText}</label>${control}`;

  const help =
    field.help && field.help !== ''
      ? `<p id="${escapeAttr(`${id}-help`)}" class="help">${escapeText(field.help)}</p>`
      : '';

  return `    <div class="form-field">\n      ${inner}\n      ${help}    </div>`.replace(/\n\s+\n/g, '\n');
}

/**
 * Render a schema into an accessible HTML <form>.
 *
 * @param {Array<{name: string, label: string, type: string,
 *                 required?: boolean, help?: string,
 *                 options?: Array<{value: string, label: string}>}>} schema
 * @returns {string} HTML markup
 */
export function renderForm(schema, { action = '', method = 'post' } = {}) {
  if (!Array.isArray(schema)) {
    throw new TypeError('renderForm expects an array of field schemas');
  }

  const fieldsHtml = schema.map(renderField).join('\n');

  return [
    '<form novalidate action="' + escapeAttr(action) + '" method="' + escapeAttr(method) + '">',
    fieldsHtml,
    '</form>',
  ]
    .filter(Boolean)
    .join('\n');
}
"})
