result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/formgen/src/form.js", "content": "/**
 * Schema-driven form HTML generator with accessibility baked in.
 *
 * Schema fields:
 *   { name, label, type, required?, help?, options? }
 *   type: text | email | number | select | checkbox | textarea
 *   options: [{ value, label }] (select only)
 */

/** Escape text for use in element content. */
function escapeText(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

/** Escape text for use inside a double-quoted attribute value. */
function escapeAttr(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function controlId(field) {
  return `field-${field.name}`;
}

function renderControl(field, id, requiredAttr, describedbyAttr) {
  switch (field.type) {
    case 'text':
    case 'email':
    case 'number':
      return `<input type="${field.type}" id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${requiredAttr}${describedbyAttr}>`;
    case 'textarea':
      return `<textarea id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${requiredAttr}${describedbyAttr}></textarea>`;
    case 'select': {
      const options = (field.options ?? [])
        .map(
          (opt) =>
            `<option value="${escapeAttr(opt.value)}">${escapeText(opt.label)}</option>`
        )
        .join('');
      return `<select id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${requiredAttr}${describedbyAttr}>${options}</select>`;
    }
    case 'checkbox':
      return `<input type="checkbox" id="${escapeAttr(id)}" name="${escapeAttr(field.name)}"${describedbyAttr}>`;
    default:
      throw new TypeError(`Unsupported field type: ${field.type}`);
  }
}

function renderField(field) {
  if (!field || typeof field.name !== 'string' || field.name === '') {
    throw new TypeError('Schema field requires a non-empty "name"');
  }

  const id = controlId(field);
  const requiredAttr = field.required ? ' required' : '';
  const describedbyAttr = field.help ? ` aria-describedby="${escapeAttr(`${id}-help`)}"` : '';

  const control = renderControl(field, id, requiredAttr, describedbyAttr);

  // Required fields get a visible asterisk inside the label, hidden from
  // assistive tech (the required attribute already conveys this).
  const asterisk = field.required ? ' <span aria-hidden="true">*</span>' : '';
  const labelText = `${escapeText(field.label)}${asterisk}`;

  // Checkbox labels wrap input-first so the control precedes its text.
  const inner =
    field.type === 'checkbox'
      ? `${control}<label for="${escapeAttr(id)}">${labelText}</label>`
      : `<label for="${escapeAttr(id)}">${labelText}</label>${control}`;

  let html = `    <div class="form-field">\n      ${inner}\n`;
  if (field.help) {
    html += `      <p id="${escapeAttr(`${id}-help`)}" class="help">${escapeText(field.help)}</p>\n`;
  }
  html += `    </div>`;
  return html;
}

/**
 * Render a schema into an accessible HTML <form> (novalidate: the server
 * owns validation semantics; the client-side hints remain for AT/UX).
 *
 * @param {Array<{name: string, label: string, type: string,
 *                 required?: boolean, help?: string,
 *                 options?: Array<{value: string, label: string}>}>} schema
 * @returns {string} HTML markup
 */
export function renderForm(schema, { action = '', method = 'post' } = {}) {
  if (!Array.isArray(schema)) {
    throw new TypeError('renderForm expects an array of field schemas');
  }
  const fieldsHtml = schema.map(renderField).join('\n');
  if (fieldsHtml === '') {
    return `<form novalidate action="${escapeAttr(action)}" method="${escapeAttr(method)}"></form>`;
  }
  return [
    `<form novalidate action="${escapeAttr(action)}" method="${escapeAttr(method)}">`,
    fieldsHtml,
    '</form>',
  ].join('\n');
}
