result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/formgen/test/form.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as cheerio from 'cheerio';
import { renderForm } from '../src/form.js';

const $ = (html) => cheerio.load(html);

const schema = [
  { name: 'username', label: 'Username', type: 'text', required: true, help: 'Your login name' },
  { name: 'email', label: 'Email', type: 'email', required: true },
  { name: 'age', label: 'Age', type: 'number' },
  {
    name: 'color',
    label: 'Color',
    type: 'select',
    options: [
      { value: '', label: 'Pick one' },
      { value: 'red', label: 'Red' },
      { value: '<script>alert("xss")</script>', label: '"><img src=x onerror=alert(1)>' },
    ],
  },
  { name: 'bio', label: 'Bio', type: 'textarea', help: 'Markdown allowed' },
  { name: 'subscribe', label: 'Subscribe to newsletter', type: 'checkbox' },
];

describe('renderForm', () => {
  it('wraps fields in a form with novalidate', () => {
    const $doc = $(renderForm(schema));
    expect($doc('form')).toHaveLength(1);
    expect($doc('form').attr('novalidate')).toBeDefined();
  });

  describe('label/control pairing via for/id for every type', () => {
    const types = ['text', 'email', 'number', 'select', 'textarea', 'checkbox'];

    for (const type of types) {
      it(`pairs label and control for ${type}`, () => {
        const html = renderForm([{ name: `fld_${type}`, label: 'A field', type }]);
        const $doc = $(html);

        const control = $doc(`#fld_fld_${type}`);
        expect(control).toHaveLength(1);

        const label = $doc(`label[for="fld_fld_${type}"]`);
        expect(label).toHaveLength(1);
        expect(label.text()).toContain('A field');

        // The referenced id belongs to the correct control type
        if (type === 'select') expect(control.is('select')).toBe(true);
        else if (type === 'textarea') expect(control.is('textarea')).toBe(true);
        else expect(control.attr('type')).toBe(type);
      });

      it(`control carries the schema name for ${type}`, () => {
        const html = renderForm([{ name: `fld_${type}`, label: 'A field', type }]);
        const $doc = $(html);
        const control =
          type === 'select'
            ? $doc('select')
            : type === 'textarea'
              ? $doc('textarea')
              : $doc(`input[type="${type}"]`);
        expect(control.attr('name')).toBe(`fld_${type}`);
      });
    }

    it('ids are deterministic across renders', () => {
      const a = renderForm([{ name: 'x', label: 'X', type: 'text' }]);
      const b = renderForm([{ name: 'x', label: 'X', type: 'text' }]);
      expect(a).toBe(b);
    });
  });

  describe('aria-describedby only present when help exists', () => {
    it('adds aria-describedby and matching help <p> when help is set', () => {
      const html = renderForm([
        { name: 'with_help', label: 'Helped', type: 'text', help: 'Some guidance' },
      ]);
      const $doc = $(html);

      expect($doc('#field-with_help').attr('aria-describedby')).toBe(
        'field-with_help-help'
      );
      const helpP = $doc('#field-with_help-help');
      expect(helpP).toHaveLength(1);
      expect(helpP.is('p')).toBe(true);
      expect(helpP.text()).toBe('Some guidance');
    });

    it('omits aria-describedby when help is absent or empty', () => {
      const html = renderForm([
        { name: 'no_help', label: 'No help', type: 'text' },
        { name: 'empty_help', label: 'Empty help', type: 'text', help: '' },
      ]);
      const $doc = $(html);

      expect($doc('#field-no_help').attr('aria-describedby')).toBeUndefined();
      expect($doc('[id$="-help"]')).toHaveLength(0);
      expect($doc('#field-empty_help').attr('aria-describedby')).toBeUndefined();
    });
  });

  describe('required fields', () => {
    it('sets the required attribute and a visible, AT-hidden asterisk in the label', () => {
      const html = renderForm([
        { name: 'req', label: 'Required field', type: 'text', required: true },
      ]);
      const $doc = $(html);

      expect($doc('#field-req').attr('required')).toBeDefined();

      const asterisk = $doc('label[for="field-req"] span');
      expect(asterisk.text()).toBe('*');
      expect(asterisk.attr('aria-hidden')).toBe('true');
    });

    it('does not mark optional fields required', () => {
      const html = renderForm([{ name: 'opt', label: 'Optional', type: 'text' }]);
      const $doc = $(html);
      expect($doc('#field-opt').attr('required')).toBeUndefined();
      expect($doc('label span[aria-hidden="true"]')).toHaveLength(0);
    });
  });

  describe('select options', () => {
    it('renders value attribute and text for each option', () => {
      const $doc = $(
        renderForm([
          {
            name: 'pick',
            label: 'Pick',
            type: 'select',
            options: [
              { value: 'a', label: 'Alpha' },
              { value: 'b', label: 'Beta' },
            ],
          },
        ])
      );

      const opts = $doc('option');
      expect(opts).toHaveLength(2);
      expect(opts.eq(0).attr('value')).toBe('a');
      expect(opts.eq(0).text()).toBe('Alpha');
      expect(opts.eq(1).attr('value')).toBe('b');
      expect(opts.eq(1).text()).toBe('Beta');
    });

    it('escapes hostile option labels so nothing executes or breaks markup', () => {
      const hostileLabel = '"><img src=x onerror=alert(1)>';
      const hostileValue = '" onmouseover="alert(1)';
      const html = renderForm([
        {
          name: 'hostile',
          label: 'Hostile',
          type: 'select',
          options: [{ value: hostileValue, label: hostileLabel }],
        },
      ]);
      const $doc = $(html);

      // Parsed structure stays intact: one select, one option, no injected img
      expect($doc('select option')).toHaveLength(1);
      expect($doc('img')).toHaveLength(0);

      const opt = $doc('option');
      expect(opt.attr('value')).toBe(hostileValue); // cheerio decodes entities
      expect(opt.text()).toBe(hostileLabel);

      // Raw markup must not contain a raw quote breakout of any attribute
      expect(html).not.toContain('<img');
    });
  });

  describe('checkbox ordering', () => {
    it('places the input before its label text', () => {
      const html = renderForm([
        { name: 'agree', label: 'I agree', type: 'checkbox' },
      ]);
      const $doc = $(html);

      const wrapper = $doc('div.form-field').first();
      const children = wrapper.children().toArray();
      expect(children[0].tagName).toBe('input');
      expect(children[1].tagName).toBe('label');

      // Label contains only the text; input sits before it as a sibling
      expect($doc(children[1]).find('input')).toHaveLength(0);
      expect($doc(children[1]).text()).toContain('I agree');
    });
  });
});
"})
